// Benchmark app: Svelte 5 (loader). Svelte's runtime asks for a Trusted Types policy when it is evaluated; see no-tt.ts.
import type { BenchApp } from "../core.ts"
import type * as SvelteApp from "./svelte-app.ts"
import { withoutPolicyLookup } from "./no-tt.ts"

export async function mount(host: HTMLElement): Promise<BenchApp> {
  const m: typeof SvelteApp = await withoutPolicyLookup(() => import("./svelte-app.ts"))
  return m.mount(host)
}

// ── svelte-app.ts
// Benchmark app: Svelte 5, the app itself (loaded by svelte.ts; the compiled component is svelte.gen.js, from
// svelte.svelte). Svelte applies state changes in a microtask, before the next paint.
import { mount as svelteMount, unmount } from "svelte"
import App from "./svelte.gen.js"
import type { BenchApp } from "../core.ts"

interface Api { run: BenchApp["run"]; add: BenchApp["add"]; update(): void; swap(): void; clear(): void }
export function mount(host: HTMLElement): BenchApp {
  const app = svelteMount(App, { target: host }) as unknown as Api
  return { run: (r) => app.run(r), add: (r) => app.add(r), update: () => app.update(), swap: () => app.swap(), clear: () => app.clear(), destroy: () => { void unmount(app as never) } }
}

// the realistic scenarios' Svelte apps ride in this chunk (see ../scenarios/libs.ts)
export { scenarios } from "../scenarios/svelte.ts"

// ── no-tt.ts
// Loads a library that asks for its own Trusted Types policy as soon as it is evaluated (Svelte, Lit). The showcase
// CSP allows no policy (trusted-types 'none'), so the lookup is hidden while the chunk loads: the library then creates
// none and falls back to plain strings, which the browser still refuses at every HTML sink. The benchmark apps never
// hand it an HTML string (Svelte compiles with fragments: "tree", Lit gets DOM-built compiled templates).
export async function withoutPolicyLookup<T>(load: () => Promise<T>): Promise<T> {
  const g = globalThis as Record<string, unknown>
  const own = Object.getOwnPropertyDescriptor(g, "trustedTypes")
  Object.defineProperty(g, "trustedTypes", { value: undefined, configurable: true, writable: true })
  try { return await load() } finally {
    if (own) Object.defineProperty(g, "trustedTypes", own)
    else delete g.trustedTypes
  }
}

